"""Patch Flutter-generated Android Gradle & Manifest files for VibeHelper permissions and minSdk."""

from __future__ import annotations

import pathlib
import re
import shutil

client_dir = pathlib.Path(__file__).resolve().parent.parent / "client-app"

# 1. Remove boilerplate widget_test.dart generated by `flutter create`
widget_test = client_dir / "test" / "widget_test.dart"
if widget_test.exists():
    widget_test.unlink()
    print("Removed generated test/widget_test.dart")

# 2. Patch AndroidManifest.xml with audio/network permissions, Android 11+ Speech query, cleartext WS
manifest = client_dir / "android" / "app" / "src" / "main" / "AndroidManifest.xml"
if manifest.exists():
    xml = manifest.read_text(encoding="utf-8")
    if "RECORD_AUDIO" not in xml:
        perms = """    <uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.RECORD_AUDIO" />
    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
    <uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS" />
    <uses-permission android:name="android.permission.WAKE_LOCK" />
    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <queries>
        <intent>
            <action android:name="android.speech.RecognitionService" />
        </intent>
    </queries>
"""
        xml = xml.replace("<application", perms + "    <application", 1)
    if "SYSTEM_ALERT_WINDOW" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW" />\n    <application',
            1,
        )
    if "POST_NOTIFICATIONS" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n    <application',
            1,
        )
    if "android.permission.VIBRATE" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.VIBRATE" />\n    <application',
            1,
        )
    if "android.permission.FOREGROUND_SERVICE" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />\n    <application',
            1,
        )
    if "FOREGROUND_SERVICE_DATA_SYNC" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_DATA_SYNC" />\n    <application',
            1,
        )
    if "REQUEST_INSTALL_PACKAGES" not in xml:
        xml = xml.replace(
            "<application",
            '    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES" />\n    <application',
            1,
        )
    if "usesCleartextTraffic" not in xml:
        xml = xml.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
    if "androidx.core.content.FileProvider" not in xml and "</application>" in xml:
        xml = xml.replace(
            "</application>",
            '        <provider\n'
            '            android:name="androidx.core.content.FileProvider"\n'
            '            android:authorities="${applicationId}.fileprovider"\n'
            '            android:exported="false"\n'
            '            android:grantUriPermissions="true">\n'
            '            <meta-data\n'
            '                android:name="android.support.FILE_PROVIDER_PATHS"\n'
            '                android:resource="@xml/vibe_update_paths" />\n'
            '        </provider>\n'
            "    </application>",
            1,
        )
    if "VibeKeepAliveService" not in xml and "</application>" in xml:
        xml = xml.replace(
            "</application>",
            '        <service\n'
            '            android:name=".VibeKeepAliveService"\n'
            '            android:exported="false"\n'
            '            android:foregroundServiceType="dataSync" />\n'
            "    </application>",
            1,
        )
    if "VibeIslandAccessibilityService" not in xml and "</application>" in xml:
        xml = xml.replace(
            "</application>",
            '        <service\n'
            '            android:name=".VibeIslandAccessibilityService"\n'
            '            android:exported="true"\n'
            '            android:label="VibeHelper 灵动中岛"\n'
            '            android:permission="android.permission.BIND_ACCESSIBILITY_SERVICE">\n'
            '            <intent-filter>\n'
            '                <action android:name="android.accessibilityservice.AccessibilityService" />\n'
            '            </intent-filter>\n'
            '            <meta-data\n'
            '                android:name="android.accessibilityservice"\n'
            '                android:resource="@xml/vibe_island_accessibility" />\n'
            '        </service>\n'
            "    </application>",
            1,
        )
    manifest.write_text(xml, encoding="utf-8")
    print("Patched AndroidManifest.xml")

# 3. Ensure minSdk >= 24 (required by flutter_webrtc / record / speech_to_text)
for gradle_name in ("build.gradle.kts", "build.gradle"):
    gradle = client_dir / "android" / "app" / gradle_name
    if gradle.exists():
        txt = gradle.read_text(encoding="utf-8")
        txt = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", txt)
        txt = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 24", txt)
        txt = re.sub(r"minSdk\s+flutter\.minSdkVersion", "minSdk 24", txt)
        gradle.write_text(txt, encoding="utf-8")
        print(f"Patched {gradle_name} minSdk -> 24")

# 4. Install custom VibeHelper launcher icons into Android res/mipmap-*
icons_src = client_dir / "assets" / "android_icons"
android_res = client_dir / "android" / "app" / "src" / "main" / "res"
if icons_src.is_dir() and android_res.is_dir():
    anydpi_dir = android_res / "mipmap-anydpi-v26"
    if anydpi_dir.is_dir():
        shutil.rmtree(anydpi_dir)
        print("Removed default mipmap-anydpi-v26")
    copied = 0
    for density_dir in icons_src.glob("mipmap-*"):
        src_icon = density_dir / "ic_launcher.png"
        if not src_icon.is_file():
            continue
        dest_dir = android_res / density_dir.name
        dest_dir.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src_icon, dest_dir / "ic_launcher.png")
        shutil.copy2(src_icon, dest_dir / "ic_launcher_round.png")
        copied += 1
    print(f"Installed custom launcher icons into {copied} mipmap densities")

if android_res.is_dir():
    values_dir = android_res / "values"
    values_dir.mkdir(parents=True, exist_ok=True)
    (values_dir / "vibehelper_strings.xml").write_text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        "<resources>\n"
        '    <string name="vibe_island_a11y_desc">用于在顶部状态栏挖孔上方显示 VibeHelper 灵动中岛并支持点击展开</string>\n'
        "</resources>\n",
        encoding="utf-8",
    )
    xml_dir = android_res / "xml"
    xml_dir.mkdir(parents=True, exist_ok=True)
    (xml_dir / "vibe_island_accessibility.xml").write_text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<accessibility-service xmlns:android="http://schemas.android.com/apk/res/android"\n'
        '    android:accessibilityEventTypes="typeWindowStateChanged"\n'
        '    android:accessibilityFeedbackType="feedbackGeneric"\n'
        '    android:accessibilityFlags="flagDefault"\n'
        '    android:canRetrieveWindowContent="false"\n'
        '    android:description="@string/vibe_island_a11y_desc"\n'
        '    android:notificationTimeout="1000" />\n',
        encoding="utf-8",
    )
    (xml_dir / "vibe_update_paths.xml").write_text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<paths xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '    <cache-path name="updates" path="updates/" />\n'
        '</paths>\n',
        encoding="utf-8",
    )
    print("Installed AccessibilityService & FileProvider XML resources")

# 5. Install native Xiaomi/Android notification, mini-window, Dynamic Island & keep-alive service
kotlin_root = client_dir / "android" / "app" / "src" / "main" / "kotlin"
overlay_dir = client_dir / "assets" / "android_overlay"
templates = [
    overlay_dir / "FloatingOverlayManager.kt",
    overlay_dir / "SystemNotificationManager.kt",
    overlay_dir / "IslandPetView.kt",
    overlay_dir / "DynamicIslandManager.kt",
    overlay_dir / "VibeKeepAliveService.kt",
    overlay_dir / "VibeIslandAccessibilityService.kt",
]
if kotlin_root.is_dir() and all(t.is_file() for t in templates):
    main_activities = list(kotlin_root.rglob("MainActivity.kt"))
    if not main_activities:
        raise FileNotFoundError(f"Could not find MainActivity.kt under {kotlin_root}")
    main_act = main_activities[0]
    raw_main = main_act.read_text(encoding="utf-8")
    pkg_match = re.search(r"^\s*package\s+([a-zA-Z0-9_.]+)", raw_main, re.MULTILINE)
    if not pkg_match:
        raise ValueError(f"Could not extract package declaration from {main_act}")
    pkg_name = pkg_match.group(1)

    for tmpl in templates:
        dest = main_act.parent / tmpl.name
        src = tmpl.read_text(encoding="utf-8").replace("__VIBEHELPER_PACKAGE__", pkg_name)
        dest.write_text(src, encoding="utf-8")

    patched_main = f"""package {pkg_name}

import android.annotation.SuppressLint
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.provider.Settings
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File

class MainActivity : FlutterActivity() {{
    private val channelName = "vibehelper/overlay"
    private val updaterChannelName = "vibehelper/updater"
    private var overlayManager: FloatingOverlayManager? = null
    private var islandManager: DynamicIslandManager? = null
    private var notifManager: SystemNotificationManager? = null
    private var overlayChannel: MethodChannel? = null
    private var updaterChannel: MethodChannel? = null
    private var notifReceiver: BroadcastReceiver? = null
    private val mainHandler = Handler(Looper.getMainLooper())

    @SuppressLint("UnspecifiedRegisterReceiverFlag")
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {{
        super.configureFlutterEngine(flutterEngine)
        val manager = FloatingOverlayManager(applicationContext)
        val island = DynamicIslandManager(applicationContext)
        val notif = SystemNotificationManager(applicationContext)
        overlayManager = manager
        islandManager = island
        notifManager = notif
        VibeIslandAccessibilityService.onConnectionChanged = {{ _ ->
            island.rebindLayerIfShowing()
        }}

        val channel = MethodChannel(flutterEngine.dartExecutor.binaryMessenger, channelName)
        overlayChannel = channel

        unregisterNotifReceiver()
        val receiver = object : BroadcastReceiver() {{
            override fun onReceive(ctx: Context?, intent: Intent?) {{
                val action = intent?.getStringExtra("action") ?: return
                val notifId = intent.getIntExtra("notif_id", -1)
                if (notifId > 0) {{
                    notif.cancelNotification(notifId)
                }}
                mainHandler.post {{
                    overlayChannel?.invokeMethod(
                        "onOverlayAction",
                        mapOf("action" to action)
                    )
                }}
            }}
        }}
        val filter = IntentFilter(notif.actionBroadcastName())
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {{
            registerReceiver(receiver, filter, Context.RECEIVER_NOT_EXPORTED)
        }} else {{
            registerReceiver(receiver, filter)
        }}
        notifReceiver = receiver

        channel.setMethodCallHandler {{ call, result ->
            when (call.method) {{
                // System notification (MIUI/HyperOS & Android)
                "canPostNotifications" -> {{
                    result.success(notif.canPostNotifications())
                }}
                "requestNotificationPermission" -> {{
                    notif.requestNotificationPermission(this)
                    result.success(true)
                }}
                "openNotificationSettings" -> {{
                    notif.openNotificationSettings(this)
                    result.success(true)
                }}
                "showSystemNotification" -> {{
                    val id = (call.argument<Number>("id")?.toInt()) ?: 1001
                    val title = call.argument<String>("title") ?: "VibeHelper"
                    val body = call.argument<String>("body") ?: ""
                    val showActions = call.argument<Boolean>("showActions") ?: false
                    notif.showNotification(
                        id = id,
                        title = title,
                        body = body,
                        showActions = showActions
                    )
                    result.success(true)
                }}
                "cancelSystemNotification" -> {{
                    val id = (call.argument<Number>("id")?.toInt()) ?: 1001
                    notif.cancelNotification(id)
                    result.success(true)
                }}

                // Compact floating mini-window
                "canDrawOverlays" -> {{
                    result.success(manager.canDrawOverlays())
                }}
                "requestOverlayPermission" -> {{
                    manager.requestOverlayPermission(this)
                    result.success(true)
                }}
                "showMiniWindow" -> {{
                    val title = call.argument<String>("title") ?: "VibeHelper"
                    val body = call.argument<String>("body") ?: ""
                    val status = call.argument<String>("status") ?: "idle"
                    val showActions = call.argument<Boolean>("showActions") ?: false
                    val isDark = call.argument<Boolean>("isDark") ?: false
                    val expanded = call.argument<Boolean>("expanded") ?: false
                    manager.showMiniWindow(
                        title = title,
                        body = body,
                        status = status,
                        showActions = showActions,
                        isDark = isDark,
                        expanded = expanded
                    ) {{ action ->
                        mainHandler.post {{
                            overlayChannel?.invokeMethod(
                                "onOverlayAction",
                                mapOf("action" to action)
                            )
                        }}
                    }}
                    result.success(true)
                }}
                "updateMiniWindow" -> {{
                    val title = call.argument<String>("title") ?: "VibeHelper"
                    val body = call.argument<String>("body") ?: ""
                    val status = call.argument<String>("status") ?: "idle"
                    val showActions = call.argument<Boolean>("showActions") ?: false
                    val isDark = call.argument<Boolean>("isDark") ?: false
                    manager.updateMiniWindow(
                        title = title,
                        body = body,
                        status = status,
                        showActions = showActions,
                        isDark = isDark
                    )
                    result.success(true)
                }}
                "hideMiniWindow" -> {{
                    manager.hideMiniWindow()
                    result.success(true)
                }}
                "isMiniWindowShowing" -> {{
                    result.success(manager.isShowing())
                }}

                // Dynamic Island overlay with pixel pet
                "isAccessibilityIslandEnabled" -> {{
                    result.success(VibeIslandAccessibilityService.isEnabled())
                }}
                "openAccessibilitySettings" -> {{
                    VibeIslandAccessibilityService.openAccessibilitySettings(this)
                    result.success(true)
                }}
                "showIsland" -> {{
                    val title = call.argument<String>("title") ?: "VibeHelper"
                    val body = call.argument<String>("body") ?: ""
                    val status = call.argument<String>("status") ?: "idle"
                    val showActions = call.argument<Boolean>("showActions") ?: false
                    val petType = call.argument<String>("petType") ?: "shiba"
                    val autoExpand = call.argument<Boolean>("autoExpand") ?: true
                    val yOffsetDp = (call.argument<Number>("yOffsetDp")?.toInt()) ?: 6
                    val widthDp = (call.argument<Number>("widthDp")?.toInt()) ?: 140
                    val expanded = call.argument<Boolean>("expanded") ?: false
                    island.showIsland(
                        title = title,
                        body = body,
                        status = status,
                        showActions = showActions,
                        petType = petType,
                        autoExpand = autoExpand,
                        yOffsetDp = yOffsetDp,
                        widthDp = widthDp,
                        expanded = expanded
                    ) {{ action ->
                        mainHandler.post {{
                            overlayChannel?.invokeMethod(
                                "onOverlayAction",
                                mapOf("action" to action)
                            )
                        }}
                    }}
                    result.success(true)
                }}
                "updateIsland" -> {{
                    val title = call.argument<String>("title") ?: "VibeHelper"
                    val body = call.argument<String>("body") ?: ""
                    val status = call.argument<String>("status") ?: "idle"
                    val showActions = call.argument<Boolean>("showActions") ?: false
                    val petType = call.argument<String>("petType") ?: "shiba"
                    val autoExpand = call.argument<Boolean>("autoExpand") ?: true
                    val yOffsetDp = (call.argument<Number>("yOffsetDp")?.toInt()) ?: 6
                    val widthDp = (call.argument<Number>("widthDp")?.toInt()) ?: 140
                    island.updateIsland(
                        title = title,
                        body = body,
                        status = status,
                        showActions = showActions,
                        petType = petType,
                        autoExpand = autoExpand,
                        yOffsetDp = yOffsetDp,
                        widthDp = widthDp
                    )
                    result.success(true)
                }}
                "hideIsland" -> {{
                    island.hideIsland()
                    result.success(true)
                }}
                "isIslandShowing" -> {{
                    result.success(island.isShowing())
                }}

                // Background keep-alive foreground service (MIUI / HyperOS)
                "startKeepAlive" -> {{
                    val subtitle = call.argument<String>("subtitle") ?: "正在后台保持宿主机实时连接"
                    VibeKeepAliveService.start(applicationContext, subtitle)
                    result.success(true)
                }}
                "stopKeepAlive" -> {{
                    VibeKeepAliveService.stop(applicationContext)
                    result.success(true)
                }}
                else -> result.notImplemented()
            }}
        }}

        val uChannel = MethodChannel(flutterEngine.dartExecutor.binaryMessenger, updaterChannelName)
        updaterChannel = uChannel
        uChannel.setMethodCallHandler {{ call, result ->
            when (call.method) {{
                "getAppVersion" -> {{
                    try {{
                        val pm = packageManager
                        val pInfo = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {{
                            pm.getPackageInfo(packageName, android.content.pm.PackageManager.PackageInfoFlags.of(0))
                        }} else {{
                            @Suppress("DEPRECATION")
                            pm.getPackageInfo(packageName, 0)
                        }}
                        val bld = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {{
                            pInfo.longVersionCode.toInt()
                        }} else {{
                            @Suppress("DEPRECATION")
                            pInfo.versionCode
                        }}
                        result.success(mapOf(
                            "version" to (pInfo.versionName ?: "0.7.0"),
                            "buildNumber" to bld,
                            "packageName" to packageName
                        ))
                    }} catch (t: Throwable) {{
                        result.success(mapOf("version" to "0.7.0", "buildNumber" to 7, "packageName" to packageName))
                    }}
                }}
                "getUpdateCacheDir" -> {{
                    val dir = File(cacheDir, "updates")
                    if (!dir.exists()) dir.mkdirs()
                    result.success(dir.absolutePath)
                }}
                "canInstallPackages" -> {{
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {{
                        result.success(packageManager.canRequestPackageInstalls())
                    }} else {{
                        result.success(true)
                    }}
                }}
                "openInstallPermissionSettings" -> {{
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {{
                        val intent = Intent(
                            Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
                            android.net.Uri.parse("package:$packageName")
                        )
                        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                        startActivity(intent)
                    }}
                    result.success(true)
                }}
                "installLocalApk" -> {{
                    val filePath = call.argument<String>("filePath") ?: ""
                    val apkFile = File(filePath)
                    if (!apkFile.exists()) {{
                        result.error("NOT_FOUND", "APK file not found: $filePath", null)
                        return@setMethodCallHandler
                    }}
                    try {{
                        val uri = FileProvider.getUriForFile(
                            applicationContext,
                            "${{packageName}}.fileprovider",
                            apkFile
                        )
                        val intent = Intent(Intent.ACTION_VIEW).apply {{
                            setDataAndType(uri, "application/vnd.android.package-archive")
                            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                        }}
                        startActivity(intent)
                        result.success(true)
                    }} catch (t: Throwable) {{
                        result.error("INSTALL_ERR", t.message ?: "Failed to launch installer", null)
                    }}
                }}
                else -> result.notImplemented()
            }}
        }}
    }}

    private fun unregisterNotifReceiver() {{
        val rec = notifReceiver ?: return
        notifReceiver = null
        try {{
            unregisterReceiver(rec)
        }} catch (_: Throwable) {{
        }}
    }}

    override fun onDestroy() {{
        VibeIslandAccessibilityService.onConnectionChanged = null
        unregisterNotifReceiver()
        overlayManager?.hideMiniWindow()
        islandManager?.hideIsland()
        overlayManager = null
        islandManager = null
        notifManager = null
        overlayChannel?.setMethodCallHandler(null)
        overlayChannel = null
        updaterChannel?.setMethodCallHandler(null)
        updaterChannel = null
        super.onDestroy()
    }}
}}
"""
    main_act.write_text(patched_main, encoding="utf-8")
    print(f"Installed native Xiaomi notification + mini-window + Dynamic Island in {main_act.parent} (pkg={pkg_name})")
